{
  "shot": {
    "composition": "手持自拍中近景，模拟35mm全画幅镜头，9:16竖屏直播画幅，使用Veo3拍摄",
    "camera_motion": "随着主体调整角度，手臂有微小的自然晃动，在8秒内有轻微的数字放大推近效果",
    "frame_rate": "24fps",
    "film_grain": "干净的数字画质，无明显颗粒感"
  },
  "subject": {
    "description": "褒姒——周幽王宠妃，肤若凝脂，眉如远山，眸似寒潭。她梳着乌黑高耸的云鬓，发间插着步摇，气质冷艳中带着一丝讥讽。",
    "wardrobe": "身穿绛红色轻罗长裙，裙上点缀着鎏金花纹，外披一层烟青色薄纱。耳戴东海珍珠耳坠，手腕上是金琥珀环。"
  },
  "scene": {
    "location": "镐京王宫外高耸的烽火台",
    "time_of_day": "黄昏",
    "environment": "烽火台上狼烟滚滚，直冲天际。夕阳的余晖将远处的群山映成暗紫色。宫廷侍卫们在背景中慌乱地奔走，旌旗在风中猎猎作响。"
  },
  "visual_details": {
    "action": "褒姒手持一面镶嵌着青铜龙纹的古镜，将其当作“手机”进行自拍直播。在她身后，周幽王正下令点燃烽火。熊熊的火光映照在她的脸上，她微微侧过头，对着镜子露出一丝微笑，轻声说道：“诸侯们，看这烟火多美…”",
    "props": "作为直播设备的青铜镜、燃烧的烽火、竹制支架、飘扬的王旗"
  },
  "cinematography": {
    "lighting": "夕阳的金橙色光与烽火的红橙色光作为主光源，与灰蓝色的狼烟形成冷暖交织的高对比度光影效果。环境光为散射光。",
    "tone": "讽刺、戏谑，带有些许荒诞感"
  },
  "audio": {
    "ambient": "旗帜在风中猎猎作响的声音、火焰燃烧的噼啪声、远处隐约传来的战鼓声、侍卫们慌乱的呼喝声，以及褒姒近距离的低语声"
  },
  "color_palette": {
    "palette": "火光的暖橙色与夕阳的金黄色，与深蓝灰色的烟幕形成鲜明对比，人物肌肤呈现柔和明亮的冷白色"
  },
  "dialogue": {
    "character": "褒姒",
    "line": "诸侯们，看这烟火多美…",
    "subtitles": false
  }
}

