  "scene": "animation",
  "style": "Futuristic Apple-style minimalism, photorealistic, cinematic lighting, seamless transitions",
  "sequence": [
    {
      "shot": "Logo Reveal",
      "camera": "slow drift-in",
      "description": "Begin in a softly lit, horizonless void. The Apple logo floats gently in the center, etched from frosted glass, catching ambient gradients and subtle specular reflections. The lighting feels calm and sacred."
    },
    {
      "transition": "A pinpoint of light touches the center of the logo, triggering a perfect circular ripple outward. As the ripple expands in slow motion, the surface of the logo distorts slightly — like it’s made of responsive fluid glass. Each ripple distorts space subtly, bending surrounding light and reflecting hints of the headset’s shape."
    },
    {
      "shot": "Product Morph",
      "camera": "continuous motion",
      "description": "With the ripple reaching full diameter, the Apple logo melts away into the reflections. At the ripple’s center, the contours of the Apple Vision Pro headset begin to rise — formed as if shaped by the expanding wave itself."
    },
    {
      "environment": "Soft gradient fog clears around the device as the environment transitions — curved white architecture and floating light panels phase into place, creating a clean showroom void around the product."
    },
    {
      "motion": "Subtle volumetric beams pass through the headset lens as it gently rotates. Light dances along the curvature of the glass and metal, suggesting inner complexity with outer elegance."
    },
    {
      "close-up": "The camera glides toward the headset’s front, macro-level detail is revealed: the smooth lens surface, the contour of the frame, and embedded sensor patterns. Reflections animate naturally with ambient motion."
    },
    {
      "ending": "The camera gently pulls back, revealing the fully formed headset resting center-frame. The Apple logo reappears beside it in a soft gradient glow. The background smooths into a clean white fade, keeping all focus on the product and brand."
    }
  ],
  "audio": {
    "soundtrack": "Ethereal, minimalist ambient tones with subtle spatial shimmer. Water-like ripple effects are blended with soft digital pulses as transitions occur. No harsh transitions — everything flows seamlessly."
  }
}

